--

COMMENT ON FUNCTION arden.actor_in_publication_audience(p_organization_id uuid, p_role_ids uuid[], p_scope_type text, p_department_id uuid) IS 'Checks active ALL_MEMBERS organization audience or an exact active role assignment; never grants Department access through ALL_MEMBERS';


