--

CREATE FUNCTION arden.actor_owns_private_membership(p_membership_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'arden', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM organization_membership om
        JOIN user_account ua ON ua.user_id = om.user_id AND ua.status = 'ACTIVE'
        JOIN organization o ON o.organization_id = om.organization_id AND o.status = 'ACTIVE'
        WHERE om.membership_id = p_membership_id AND om.status = 'ACTIVE'
          AND om.user_id = NULLIF(current_setting('arden.actor_id', true), '')::uuid
          AND om.organization_id = NULLIF(current_setting('arden.organization_id', true), '')::uuid
    );
$$;


--
-- Name: advance_draft_current_version(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.advance_draft_current_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE draft_document
       SET current_version_no = GREATEST(current_version_no, NEW.version_no)
     WHERE draft_id = NEW.draft_id;
    RETURN NEW;
END;
$$;


--
-- Name: advance_shared_draft_current_version(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.advance_shared_draft_current_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE shared_draft SET current_version_no = NEW.version_no
     WHERE shared_draft_id = NEW.shared_draft_id AND current_version_no = NEW.version_no - 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Shared draft version must advance by exactly one'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: apply_review_decision(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.apply_review_decision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE new_generation_id uuid;
BEGIN
    UPDATE shared_submission
       SET status = NEW.decision,
           publication_state = CASE WHEN NEW.decision = 'APPROVED' THEN 'PREPARING' ELSE 'NONE' END
     WHERE submission_id = NEW.submission_id;

    IF NEW.flow2 AND NEW.decision = 'APPROVED' THEN
        new_generation_id := gen_random_uuid();
        INSERT INTO knowledge_index_generation (
            generation_id, organization_id, submission_id, shared_draft_id,
            snapshot_version_id, snapshot_content_hash)
        SELECT new_generation_id, organization_id, submission_id, shared_draft_id,
               shared_draft_version_id, content_hash
          FROM shared_submission
         WHERE submission_id = NEW.submission_id;

        INSERT INTO knowledge_index_job (generation_id) VALUES (new_generation_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: audience_snapshot_enforceable(uuid, uuid[], text, uuid); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.audience_snapshot_enforceable(requested_organization_id uuid, requested_audience_ids uuid[], requested_scope_type text, requested_department_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
    SELECT coalesce(array_length(requested_audience_ids, 1), 0) > 0
       AND coalesce(array_length(requested_audience_ids, 1), 0) <= 100
       AND cardinality(requested_audience_ids) = cardinality(ARRAY(SELECT DISTINCT unnest(requested_audience_ids)))
       AND NOT EXISTS (
           SELECT 1 FROM unnest(requested_audience_ids) requested(audience_id)
           LEFT JOIN audience a ON a.audience_id = requested.audience_id
             AND a.organization_id = requested_organization_id AND a.status = 'ACTIVE'
          WHERE a.audience_id IS NULL
             OR (a.kind = 'ORGANIZATION_ALL' AND requested_scope_type <> 'ORGANIZATION')
             OR (a.kind = 'DEPARTMENT_ALL' AND
                 (requested_scope_type <> 'DEPARTMENT' OR a.department_id IS DISTINCT FROM requested_department_id))
       );
$$;


--
-- Name: claim_knowledge_index_job(uuid, integer); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.claim_knowledge_index_job(p_worker_id uuid, p_lease_seconds integer DEFAULT 90) RETURNS TABLE(job_id uuid, generation_id uuid, organization_id uuid, submission_id uuid, snapshot_version_id uuid, snapshot_content_hash text, source_uri text, mime_type text, attempt_count integer, max_attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
BEGIN
    IF p_worker_id IS NULL OR p_lease_seconds NOT BETWEEN 15 AND 600 THEN
        RAISE EXCEPTION 'Invalid indexing worker lease request' USING ERRCODE = '22023';
    END IF;

    -- A worker may disappear after claiming its final allowed attempt. Close
    -- such an expired lease before selecting another job so it cannot remain
    -- RUNNING forever.
    WITH exhausted AS (
        UPDATE knowledge_index_job j
           SET status = 'FAILED', lease_owner = NULL, lease_expires_at = NULL,
               last_error_code = 'INDEXING_LEASE_EXHAUSTED', completed_at = now()
         WHERE j.status = 'RUNNING' AND j.lease_expires_at <= now()
           AND j.attempt_count >= j.max_attempts
        RETURNING j.generation_id
    ), failed_generations AS (
        UPDATE knowledge_index_generation g
           SET status = 'FAILED', failure_code = 'INDEXING_LEASE_EXHAUSTED', completed_at = now()
          FROM exhausted e
         WHERE g.generation_id = e.generation_id
        RETURNING g.submission_id
    )
    UPDATE shared_submission s SET publication_state = 'FAILED'
      FROM failed_generations f
     WHERE s.submission_id = f.submission_id
       AND s.status = 'APPROVED' AND s.publication_state = 'PREPARING';

    RETURN QUERY
    WITH candidate AS (
        SELECT j.job_id
          FROM knowledge_index_job j
          JOIN knowledge_index_generation g ON g.generation_id = j.generation_id
          JOIN shared_submission s ON s.submission_id = g.submission_id
         WHERE ((j.status = 'PENDING' AND j.available_at <= now())
            OR (j.status = 'RUNNING' AND j.lease_expires_at <= now()))
           AND j.attempt_count < j.max_attempts
           AND g.status IN ('PENDING', 'PROCESSING')
           AND s.status = 'APPROVED' AND s.publication_state = 'PREPARING'
         ORDER BY j.available_at, j.created_at, j.job_id
         FOR UPDATE SKIP LOCKED
         LIMIT 1
    ), claimed AS (
        UPDATE knowledge_index_job j
           SET status = 'RUNNING',
               attempt_count = j.attempt_count + 1,
               lease_owner = p_worker_id,
               lease_expires_at = now() + make_interval(secs => p_lease_seconds),
               last_error_code = NULL
          FROM candidate c
         WHERE j.job_id = c.job_id AND j.attempt_count < j.max_attempts
        RETURNING j.*
    ), started AS (
        UPDATE knowledge_index_generation g
           SET status = 'PROCESSING', started_at = COALESCE(g.started_at, now())
          FROM claimed c
         WHERE g.generation_id = c.generation_id
        RETURNING g.*
    )
    SELECT c.job_id, g.generation_id, g.organization_id, g.submission_id,
           g.snapshot_version_id, g.snapshot_content_hash,
           s.content_uri, s.mime_type, c.attempt_count, c.max_attempts
      FROM claimed c
      JOIN started g ON g.generation_id = c.generation_id
      JOIN shared_submission s ON s.submission_id = g.submission_id
     WHERE s.status = 'APPROVED' AND s.publication_state = 'PREPARING'
       AND s.shared_draft_version_id = g.snapshot_version_id
       AND s.content_hash = g.snapshot_content_hash;
END;
$$;


--
-- Name: complete_knowledge_index_job(uuid, uuid, jsonb); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.complete_knowledge_index_job(p_job_id uuid, p_worker_id uuid, p_manifest jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE
    draft_id uuid;
    candidate_version integer;
    newest_published_version integer;
    result_id uuid;
BEGIN
    SELECT g.shared_draft_id INTO STRICT draft_id
      FROM knowledge_index_job j JOIN knowledge_index_generation g USING (generation_id)
     WHERE j.job_id = p_job_id;
    -- Every activation for this draft holds the same lock before inspecting
    -- history or moving the current pointer. The next statement sees the
    -- preceding activation's committed state under READ COMMITTED.
    PERFORM 1 FROM shared_draft WHERE shared_draft_id = draft_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Index draft is unavailable' USING ERRCODE = '23514'; END IF;

    SELECT s.snapshot_version_no INTO STRICT candidate_version
      FROM knowledge_index_job j JOIN knowledge_index_generation g USING (generation_id)
      JOIN shared_submission s ON s.submission_id = g.submission_id
     WHERE j.job_id = p_job_id;
    -- Publication history remains a high-water mark even after unpublication;
    -- deleting a pointer must not enable an older delayed job to resurrect it.
    SELECT max(s.snapshot_version_no) INTO newest_published_version
      FROM published_knowledge_version pv JOIN shared_submission s USING (submission_id)
     WHERE pv.shared_draft_id = draft_id;
    IF newest_published_version >= candidate_version THEN
        RAISE EXCEPTION 'Index generation is superseded by a published snapshot' USING ERRCODE = 'AR001';
    END IF;

    result_id := complete_knowledge_index_job_unordered_v1(p_job_id, p_worker_id, p_manifest);
    UPDATE shared_submission SET publication_state = 'SUPERSEDED'
     WHERE shared_draft_id = draft_id AND publication_state = 'ACTIVE'
       AND submission_id <> (SELECT submission_id FROM published_knowledge_version WHERE published_version_id = result_id);
    RETURN result_id;
END;
$$;


--
-- Name: complete_knowledge_index_job_unordered_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.complete_knowledge_index_job_unordered_v1(p_job_id uuid, p_worker_id uuid, p_manifest jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $_$
DECLARE
    job_row knowledge_index_job%ROWTYPE;
    generation_row knowledge_index_generation%ROWTYPE;
    submission_row shared_submission%ROWTYPE;
    knowledge_base_id_value uuid;
    published_version_id_value uuid;
    decision_id uuid;
BEGIN
    IF p_manifest IS NULL OR jsonb_typeof(p_manifest) <> 'object' THEN
        RAISE EXCEPTION 'Index manifest must be an object' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO STRICT job_row FROM knowledge_index_job
     WHERE knowledge_index_job.job_id = p_job_id FOR UPDATE;
    IF job_row.status <> 'RUNNING' OR job_row.lease_owner IS DISTINCT FROM p_worker_id
       OR job_row.lease_expires_at <= now() THEN
        RAISE EXCEPTION 'Index job lease is no longer valid' USING ERRCODE = '40001';
    END IF;

    SELECT * INTO STRICT generation_row FROM knowledge_index_generation
     WHERE knowledge_index_generation.generation_id = job_row.generation_id FOR UPDATE;
    SELECT * INTO STRICT submission_row FROM shared_submission
     WHERE shared_submission.submission_id = generation_row.submission_id FOR UPDATE;

    IF generation_row.status <> 'PROCESSING'
       OR submission_row.status <> 'APPROVED'
       OR submission_row.publication_state <> 'PREPARING'
       OR submission_row.shared_draft_version_id IS DISTINCT FROM generation_row.snapshot_version_id
       OR submission_row.content_hash IS DISTINCT FROM generation_row.snapshot_content_hash
       OR NOT audience_snapshot_enforceable(submission_row.organization_id,
            submission_row.audience_role_ids, submission_row.target_scope_type,
            submission_row.target_department_id) THEN
        RAISE EXCEPTION 'Index generation is no longer activatable' USING ERRCODE = '23514';
    END IF;

    IF p_manifest->>'jobId' IS DISTINCT FROM p_job_id::text
       OR p_manifest->>'generationId' IS DISTINCT FROM generation_row.generation_id::text
       OR p_manifest->>'snapshotVersionId' IS DISTINCT FROM generation_row.snapshot_version_id::text
       OR p_manifest->>'snapshotContentHash' IS DISTINCT FROM generation_row.snapshot_content_hash
       OR p_manifest->>'contractVersion' IS DISTINCT FROM '1'
       OR COALESCE(p_manifest->>'compilerVersion', '') = ''
       OR COALESCE(p_manifest->>'chunkingVersion', '') = ''
       OR COALESCE(p_manifest->>'embeddingModel', '') = ''
       OR COALESCE((p_manifest->>'embeddingDimensions')::integer, 0) <= 0
       OR COALESCE(p_manifest->>'markdownContentHash', '') !~ '^[0-9a-f]{64}$'
       OR COALESCE(p_manifest->>'chunksDigest', '') !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(p_manifest->'chunks') <> 'array'
       OR jsonb_array_length(p_manifest->'chunks') = 0 THEN
        RAISE EXCEPTION 'Index manifest does not match the claimed generation' USING ERRCODE = '23514';
    END IF;

    INSERT INTO knowledge_base (organization_id, department_id, name, scope_type)
    VALUES (submission_row.organization_id, submission_row.target_department_id,
            'Arden Knowledge', submission_row.target_scope_type)
    ON CONFLICT DO NOTHING;

    SELECT kb.knowledge_base_id INTO STRICT knowledge_base_id_value
      FROM knowledge_base kb
     WHERE kb.organization_id = submission_row.organization_id
       AND kb.name = 'Arden Knowledge'
       AND kb.scope_type = submission_row.target_scope_type
       AND kb.department_id IS NOT DISTINCT FROM submission_row.target_department_id
       AND kb.status = 'ACTIVE';

    INSERT INTO published_knowledge_version (
        submission_id, knowledge_base_id, published_by_membership_id,
        shared_draft_id, title, version_no, content_uri, content_hash,
        index_status, classification, responsible_department_id,
        audience_role_ids, valid_from, valid_until)
    VALUES (
        submission_row.submission_id, knowledge_base_id_value, NULL,
        submission_row.shared_draft_id, submission_row.title,
        nextval('flow2_publication_version_seq'), submission_row.content_uri,
        submission_row.content_hash, 'INDEXED', submission_row.classification,
        submission_row.responsible_department_id, submission_row.audience_role_ids,
        now(), NULL)
    RETURNING published_version_id INTO STRICT published_version_id_value;

    INSERT INTO knowledge_current_publication (
        shared_draft_id, organization_id, published_version_id,
        audience_role_ids, target_scope_type, target_department_id,
        valid_from, valid_until)
    VALUES (
        submission_row.shared_draft_id, submission_row.organization_id,
        published_version_id_value, submission_row.audience_role_ids,
        submission_row.target_scope_type, submission_row.target_department_id,
        now(), NULL)
    ON CONFLICT (shared_draft_id) DO UPDATE SET
        published_version_id = EXCLUDED.published_version_id,
        audience_role_ids = EXCLUDED.audience_role_ids,
        target_scope_type = EXCLUDED.target_scope_type,
        target_department_id = EXCLUDED.target_department_id,
        valid_from = EXCLUDED.valid_from,
        valid_until = EXCLUDED.valid_until,
        updated_at = now();

    UPDATE knowledge_index_generation
       SET status = 'READY', manifest_json = p_manifest, completed_at = now()
     WHERE generation_id = generation_row.generation_id;
    UPDATE knowledge_index_job
       SET status = 'SUCCEEDED', lease_owner = NULL, lease_expires_at = NULL,
           completed_at = now()
     WHERE knowledge_index_job.job_id = p_job_id;
    UPDATE shared_submission SET publication_state = 'ACTIVE'
     WHERE submission_id = submission_row.submission_id;

    SELECT rd.review_decision_id INTO STRICT decision_id
      FROM review_decision rd
     WHERE rd.submission_id = submission_row.submission_id
       AND rd.flow2 AND rd.decision = 'APPROVED';
    INSERT INTO audit_event (
        organization_id, actor_membership_id, review_decision_id,
        event_type, outcome, details_json)
    VALUES (
        submission_row.organization_id, NULL, decision_id,
        'KNOWLEDGE_INDEX_ACTIVATED', 'SUCCESS',
        jsonb_build_object(
            'jobId', p_job_id,
            'generationId', generation_row.generation_id,
            'publishedVersionId', published_version_id_value,
            'snapshotVersionId', generation_row.snapshot_version_id));

    RETURN published_version_id_value;
END;
$_$;


--
-- Name: enforce_flow2_review_outcome(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.enforce_flow2_review_outcome() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE submission_row record; publication_count integer;
BEGIN
    IF NOT NEW.flow2 THEN RETURN NEW; END IF;
    SELECT status, publication_state, organization_id, responsible_department_id,
           classification, team_tag, project_tag
      INTO STRICT submission_row FROM shared_submission WHERE submission_id = NEW.submission_id;
    IF submission_row.status IS DISTINCT FROM NEW.decision THEN
        RAISE EXCEPTION 'Review decision and submission status diverged' USING ERRCODE = '23514';
    END IF;
    IF COALESCE(current_setting('arden.org_admin', true), 'false') <> 'true'
       AND NOT actor_has_reviewer_grant(submission_row.organization_id,
           submission_row.responsible_department_id, submission_row.classification,
           submission_row.team_tag, submission_row.project_tag) THEN
        RAISE EXCEPTION 'Review decision lacks current reviewer authority' USING ERRCODE = '23514';
    END IF;
    SELECT count(*) INTO publication_count FROM published_knowledge_version
     WHERE submission_id = NEW.submission_id;
    IF NEW.decision = 'APPROVED' THEN
        IF submission_row.publication_state <> 'PREPARING' OR publication_count <> 0 THEN
            RAISE EXCEPTION 'Approval must enter PREPARING without activating a publication'
                USING ERRCODE = '23514';
        END IF;
    ELSIF publication_count <> 0 THEN
        RAISE EXCEPTION 'Rejected submission cannot be published' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM audit_event a WHERE a.review_decision_id = NEW.review_decision_id
        AND a.event_type = 'KNOWLEDGE_REVIEW_DECIDED' AND a.outcome = 'SUCCESS') THEN
        RAISE EXCEPTION 'Review decision needs a separate audit record' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fail_knowledge_index_job(uuid, uuid, text, boolean); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.fail_knowledge_index_job(p_job_id uuid, p_worker_id uuid, p_error_code text, p_retryable boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $_$
DECLARE
    job_row knowledge_index_job%ROWTYPE;
    terminal boolean;
BEGIN
    IF p_error_code IS NULL OR p_error_code !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN
        RAISE EXCEPTION 'Invalid indexing failure code' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO STRICT job_row FROM knowledge_index_job
     WHERE knowledge_index_job.job_id = p_job_id FOR UPDATE;
    IF job_row.status <> 'RUNNING' OR job_row.lease_owner IS DISTINCT FROM p_worker_id THEN
        RAISE EXCEPTION 'Index job lease is no longer valid' USING ERRCODE = '40001';
    END IF;

    terminal := NOT p_retryable OR job_row.attempt_count >= job_row.max_attempts;
    IF terminal THEN
        UPDATE knowledge_index_job
           SET status = 'FAILED', lease_owner = NULL, lease_expires_at = NULL,
               last_error_code = p_error_code, completed_at = now()
         WHERE knowledge_index_job.job_id = p_job_id;
        UPDATE knowledge_index_generation
           SET status = 'FAILED', failure_code = p_error_code, completed_at = now()
         WHERE generation_id = job_row.generation_id;
        UPDATE shared_submission s SET publication_state = CASE
            WHEN p_error_code = 'INDEX_GENERATION_SUPERSEDED' THEN 'SUPERSEDED'
            ELSE 'FAILED' END
          FROM knowledge_index_generation g
         WHERE g.generation_id = job_row.generation_id
           AND s.submission_id = g.submission_id
           AND s.status = 'APPROVED' AND s.publication_state = 'PREPARING';
        RETURN 'FAILED';
    END IF;

    UPDATE knowledge_index_job
       SET status = 'PENDING', lease_owner = NULL, lease_expires_at = NULL,
           last_error_code = p_error_code,
           available_at = now() + make_interval(secs => LEAST(60, 5 * (2 ^ (job_row.attempt_count - 1))))
     WHERE knowledge_index_job.job_id = p_job_id;
    UPDATE knowledge_index_generation
       SET status = 'PENDING', started_at = NULL
     WHERE generation_id = job_row.generation_id;
    RETURN 'PENDING';
END;
$_$;


--
-- Name: organization_has_active_reviewer_grant(uuid); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.organization_has_active_reviewer_grant(p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM organization_membership caller
        JOIN user_account caller_user ON caller_user.user_id = caller.user_id
          AND caller_user.status = 'ACTIVE'
        JOIN organization o ON o.organization_id = caller.organization_id AND o.status = 'ACTIVE'
        WHERE caller.user_id = NULLIF(current_setting('arden.actor_id', true), '')::uuid
          AND caller.organization_id = p_organization_id
          AND caller.status = 'ACTIVE')
      AND EXISTS (
        SELECT 1 FROM reviewer_grant g
        JOIN organization_membership reviewer
          ON reviewer.membership_id = g.reviewer_membership_id
         AND reviewer.organization_id = g.organization_id
         AND reviewer.status = 'ACTIVE'
        JOIN user_account reviewer_user ON reviewer_user.user_id = reviewer.user_id
         AND reviewer_user.status = 'ACTIVE'
        WHERE g.organization_id = p_organization_id
          AND g.scope = 'ORGANIZATION'
          AND g.status = 'ACTIVE'
          AND g.valid_from <= now()
          AND (g.valid_until IS NULL OR g.valid_until > now()));
$$;


--
-- Name: protect_flow2_published_metadata(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.protect_flow2_published_metadata() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.shared_draft_id IS NOT NULL AND
       (NEW.shared_draft_id, NEW.classification, NEW.responsible_department_id,
        NEW.audience_role_ids, NEW.valid_from, NEW.valid_until)
       IS DISTINCT FROM
       (OLD.shared_draft_id, OLD.classification, OLD.responsible_department_id,
        OLD.audience_role_ids, OLD.valid_from, OLD.valid_until) THEN
        RAISE EXCEPTION 'Published governance metadata is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: protect_flow2_submission_snapshot(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.protect_flow2_submission_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.shared_draft_version_id IS NOT NULL AND
       (NEW.shared_draft_version_id, NEW.shared_draft_id, NEW.snapshot_version_no,
        NEW.organization_id, NEW.submitted_by_membership_id,
        NEW.target_scope_type, NEW.target_department_id, NEW.responsible_department_id,
        NEW.title, NEW.classification, NEW.team_tag, NEW.project_tag,
        NEW.audience_role_ids, NEW.policy_version, NEW.review_rule, NEW.content_uri, NEW.mime_type,
        NEW.content_hash, NEW.submit_request_id)
       IS DISTINCT FROM
       (OLD.shared_draft_version_id, OLD.shared_draft_id, OLD.snapshot_version_no,
        OLD.organization_id, OLD.submitted_by_membership_id,
        OLD.target_scope_type, OLD.target_department_id, OLD.responsible_department_id,
        OLD.title, OLD.classification, OLD.team_tag, OLD.project_tag,
        OLD.audience_role_ids, OLD.policy_version, OLD.review_rule, OLD.content_uri, OLD.mime_type,
        OLD.content_hash, OLD.submit_request_id) THEN
        RAISE EXCEPTION 'Submitted snapshot is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: protect_last_system_administrator(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.protect_last_system_administrator() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
BEGIN
    IF OLD.status = 'ACTIVE' THEN
        IF (TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND NEW.status <> 'ACTIVE'))
           AND NOT EXISTS (
               SELECT 1 FROM system_administrator other
                WHERE other.status = 'ACTIVE' AND other.user_id <> OLD.user_id
           ) THEN
            RAISE EXCEPTION 'The last active Arden System Admin cannot be removed'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: protect_published_version_content(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.protect_published_version_content() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'published_knowledge_version is immutable: DELETE is not allowed'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.submission_id IS DISTINCT FROM OLD.submission_id
       OR NEW.knowledge_base_id IS DISTINCT FROM OLD.knowledge_base_id
       OR NEW.published_by_membership_id IS DISTINCT FROM OLD.published_by_membership_id
       OR NEW.title IS DISTINCT FROM OLD.title
       OR NEW.version_no IS DISTINCT FROM OLD.version_no
       OR NEW.content_uri IS DISTINCT FROM OLD.content_uri
       OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
       OR NEW.published_at IS DISTINCT FROM OLD.published_at THEN
        RAISE EXCEPTION 'Published content and provenance are immutable; create a new version instead'
            USING ERRCODE = '55000';
    END IF;

    -- index_status is intentionally mutable so the indexing worker can move
    -- PENDING -> PROCESSING -> INDEXED/FAILED without rewriting content.
    RETURN NEW;
END;
$$;


--
-- Name: protect_shared_draft_provenance(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.protect_shared_draft_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
       OR NEW.author_membership_id IS DISTINCT FROM OLD.author_membership_id
       OR NEW.source_private_version_id IS DISTINCT FROM OLD.source_private_version_id
       OR NEW.source_published_version_id IS DISTINCT FROM OLD.source_published_version_id THEN
        RAISE EXCEPTION 'Shared draft provenance is immutable'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_pending_shared_draft_audience_change(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.reject_pending_shared_draft_audience_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE draft_id uuid;
BEGIN
    IF TG_OP = 'DELETE' THEN draft_id := OLD.shared_draft_id;
    ELSE draft_id := NEW.shared_draft_id; END IF;
    PERFORM 1 FROM shared_draft WHERE shared_draft_id = draft_id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM shared_submission
        WHERE shared_draft_id = draft_id AND status = 'PENDING_REVIEW') THEN
        RAISE EXCEPTION 'Shared draft audience cannot change during pending review' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_pending_shared_draft_change(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.reject_pending_shared_draft_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'arden', 'pg_temp'
    AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM shared_submission s
        JOIN shared_draft_version v ON v.shared_draft_version_id = s.shared_draft_version_id
        WHERE v.shared_draft_id = NEW.shared_draft_id AND s.status = 'PENDING_REVIEW') THEN
        RAISE EXCEPTION 'Shared draft cannot change while a snapshot is pending review' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_row_mutation(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.reject_row_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION '% is immutable: % is not allowed', TG_TABLE_NAME, TG_OP
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


--
-- Name: validate_audience_group_membership(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_audience_group_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM audience a
         WHERE a.audience_id = NEW.audience_id
           AND a.organization_id = NEW.organization_id
           AND a.kind = 'GROUP' AND a.status = 'ACTIVE'
    ) THEN
        RAISE EXCEPTION 'Audience group membership requires an active group audience'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_audit_event_tenant(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_audit_event_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE
    related_org uuid;
BEGIN
    IF NEW.actor_membership_id IS NOT NULL THEN
        SELECT organization_id
          INTO STRICT related_org
          FROM organization_membership
         WHERE membership_id = NEW.actor_membership_id;

        IF related_org <> NEW.organization_id THEN
            RAISE EXCEPTION 'Audit actor must belong to the audit organization'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.role_assignment_id IS NOT NULL THEN
        SELECT m.organization_id
          INTO STRICT related_org
          FROM role_assignment ra
          JOIN organization_membership m ON m.membership_id = ra.membership_id
         WHERE ra.role_assignment_id = NEW.role_assignment_id;

        IF related_org <> NEW.organization_id THEN
            RAISE EXCEPTION 'Audited role assignment belongs to another organization'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.review_decision_id IS NOT NULL THEN
        SELECT COALESCE(s.organization_id, reviewer.organization_id)
          INTO STRICT related_org
          FROM review_decision rd
          JOIN shared_submission s ON s.submission_id = rd.submission_id
          JOIN organization_membership reviewer
            ON reviewer.membership_id = rd.reviewer_membership_id
         WHERE rd.review_decision_id = NEW.review_decision_id;

        IF related_org <> NEW.organization_id THEN
            RAISE EXCEPTION 'Audited review decision belongs to another organization'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.question_id IS NOT NULL THEN
        SELECT m.organization_id
          INTO STRICT related_org
          FROM user_question q
          JOIN organization_membership m ON m.membership_id = q.membership_id
         WHERE q.question_id = NEW.question_id;

        IF related_org <> NEW.organization_id THEN
            RAISE EXCEPTION 'Audited question belongs to another organization'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_citation_tenant_scope(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_citation_tenant_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    question_membership uuid;
    question_org        uuid;
    knowledge_org       uuid;
    knowledge_scope     text;
    knowledge_department uuid;
    has_department_access boolean;
BEGIN
    SELECT q.membership_id, m.organization_id
      INTO STRICT question_membership, question_org
      FROM ai_response r
      JOIN user_question q ON q.question_id = r.question_id
      JOIN organization_membership m ON m.membership_id = q.membership_id
     WHERE r.response_id = NEW.response_id;

    SELECT kb.organization_id, kb.scope_type, kb.department_id
      INTO STRICT knowledge_org, knowledge_scope, knowledge_department
      FROM knowledge_chunk c
      JOIN published_knowledge_version pv
        ON pv.published_version_id = c.published_version_id
      JOIN knowledge_base kb
        ON kb.knowledge_base_id = pv.knowledge_base_id
     WHERE c.chunk_id = NEW.chunk_id;

    IF question_org <> knowledge_org THEN
        RAISE EXCEPTION 'Citation cannot expose knowledge from another organization'
            USING ERRCODE = '23514';
    END IF;

    IF knowledge_scope = 'DEPARTMENT' THEN
        SELECT EXISTS (
            SELECT 1
              FROM department_membership dm
             WHERE dm.membership_id = question_membership
               AND dm.department_id = knowledge_department
               AND dm.status = 'ACTIVE'
        ) INTO has_department_access;

        IF NOT has_department_access THEN
            RAISE EXCEPTION 'Question membership cannot cite an inaccessible department chunk'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_current_publication(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_current_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE publication_row record;
BEGIN
    SELECT pv.shared_draft_id, pv.audience_role_ids, pv.valid_from, pv.valid_until,
           kb.organization_id, kb.scope_type, kb.department_id
      INTO STRICT publication_row FROM published_knowledge_version pv
      JOIN knowledge_base kb ON kb.knowledge_base_id = pv.knowledge_base_id
     WHERE pv.published_version_id = NEW.published_version_id;
    IF publication_row.shared_draft_id IS DISTINCT FROM NEW.shared_draft_id
        OR publication_row.organization_id IS DISTINCT FROM NEW.organization_id
        OR publication_row.audience_role_ids IS DISTINCT FROM NEW.audience_role_ids
        OR publication_row.scope_type IS DISTINCT FROM NEW.target_scope_type
        OR publication_row.department_id IS DISTINCT FROM NEW.target_department_id
        OR publication_row.valid_from IS DISTINCT FROM NEW.valid_from
        OR publication_row.valid_until IS DISTINCT FROM NEW.valid_until THEN
        RAISE EXCEPTION 'Current pointer must exactly match its published version' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_department_membership(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_department_membership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    membership_org uuid;
    department_org uuid;
BEGIN
    SELECT organization_id
      INTO STRICT membership_org
      FROM organization_membership
     WHERE membership_id = NEW.membership_id;

    SELECT organization_id
      INTO STRICT department_org
      FROM department
     WHERE department_id = NEW.department_id;

    IF membership_org <> department_org THEN
        RAISE EXCEPTION 'Membership and department must belong to the same organization'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_draft_version_creator(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_draft_version_creator() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owner_membership uuid;
    owner_org        uuid;
    creator_org      uuid;
BEGIN
    SELECT w.membership_id, m.organization_id
      INTO STRICT owner_membership, owner_org
      FROM draft_document d
      JOIN private_workspace w ON w.workspace_id = d.workspace_id
      JOIN organization_membership m ON m.membership_id = w.membership_id
     WHERE d.draft_id = NEW.draft_id;

    SELECT organization_id
      INTO STRICT creator_org
      FROM organization_membership
     WHERE membership_id = NEW.created_by_membership_id;

    IF owner_org <> creator_org THEN
        RAISE EXCEPTION 'Draft version creator cannot cross organization boundaries'
            USING ERRCODE = '23514';
    END IF;

    -- Authorization for a non-owner creator remains an application-level RBAC
    -- decision; this trigger only guarantees tenant isolation.
    RETURN NEW;
END;
$$;


--
-- Name: validate_published_version(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_published_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE
    submission_row record;
    knowledge_row record;
    submission_org uuid;
    publisher_org uuid;
BEGIN
    SELECT s.*
      INTO STRICT submission_row
      FROM shared_submission s
     WHERE s.submission_id = NEW.submission_id;

    SELECT organization_id, scope_type, department_id
      INTO STRICT knowledge_row
      FROM knowledge_base
     WHERE knowledge_base_id = NEW.knowledge_base_id;

    IF submission_row.shared_draft_version_id IS NOT NULL THEN
        submission_org := submission_row.organization_id;
    ELSE
        SELECT organization_id
          INTO STRICT submission_org
          FROM organization_membership
         WHERE membership_id = submission_row.submitted_by_membership_id;
    END IF;

    IF submission_row.status <> 'APPROVED'
        OR submission_org IS DISTINCT FROM knowledge_row.organization_id THEN
        RAISE EXCEPTION 'Publication requires an approved same-organization submission'
            USING ERRCODE = '23514';
    END IF;

    IF submission_row.shared_draft_version_id IS NOT NULL THEN
        IF NEW.published_by_membership_id IS NOT NULL
            OR NOT EXISTS (SELECT 1 FROM review_decision rd
                WHERE rd.submission_id = NEW.submission_id AND rd.flow2 AND rd.decision = 'APPROVED')
            OR NEW.shared_draft_id IS DISTINCT FROM submission_row.shared_draft_id
            OR NEW.title IS DISTINCT FROM submission_row.title
            OR NEW.classification IS DISTINCT FROM submission_row.classification
            OR NEW.responsible_department_id IS DISTINCT FROM submission_row.responsible_department_id
            OR NEW.audience_role_ids IS DISTINCT FROM submission_row.audience_role_ids
            OR NEW.content_uri IS DISTINCT FROM submission_row.content_uri
            OR NEW.content_hash IS DISTINCT FROM submission_row.content_hash
            OR NEW.valid_from IS NULL
            OR knowledge_row.scope_type IS DISTINCT FROM submission_row.target_scope_type
            OR knowledge_row.department_id IS DISTINCT FROM submission_row.target_department_id THEN
            RAISE EXCEPTION 'System publication must match the exact approved snapshot and scope'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        SELECT organization_id
          INTO STRICT publisher_org
          FROM organization_membership
         WHERE membership_id = NEW.published_by_membership_id;

        IF publisher_org IS DISTINCT FROM submission_org THEN
            RAISE EXCEPTION 'Legacy publisher belongs to another organization'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_review_decision(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_review_decision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE submission_row record; reviewer_org uuid; is_org_admin boolean;
BEGIN
    SELECT s.submitted_by_membership_id, s.organization_id, s.shared_draft_version_id,
           s.content_hash, s.responsible_department_id, s.classification,
           s.team_tag, s.project_tag, s.audience_role_ids, s.status
      INTO STRICT submission_row FROM shared_submission s WHERE s.submission_id = NEW.submission_id;
    SELECT organization_id INTO STRICT reviewer_org FROM organization_membership
     WHERE membership_id = NEW.reviewer_membership_id;
    is_org_admin := COALESCE(current_setting('arden.org_admin', true), 'false') = 'true';
    IF reviewer_org IS DISTINCT FROM submission_row.organization_id
       OR (NEW.reviewer_membership_id = submission_row.submitted_by_membership_id AND NOT is_org_admin) THEN
        RAISE EXCEPTION 'Reviewer authority does not cover this submission' USING ERRCODE = '23514';
    END IF;
    IF submission_row.shared_draft_version_id IS NOT NULL THEN
        IF NOT NEW.flow2
            OR NEW.snapshot_version_id IS DISTINCT FROM submission_row.shared_draft_version_id
            OR NEW.content_hash IS DISTINCT FROM submission_row.content_hash
            OR (NOT is_org_admin AND NOT actor_has_reviewer_grant(submission_row.organization_id,
                submission_row.responsible_department_id, submission_row.classification,
                submission_row.team_tag, submission_row.project_tag)) THEN
            RAISE EXCEPTION 'Review decision does not match a live authorized snapshot' USING ERRCODE = '23514';
        END IF;
        IF NEW.decision = 'APPROVED' AND NOT audience_snapshot_enforceable(
            submission_row.organization_id, submission_row.audience_role_ids,
            (SELECT target_scope_type FROM shared_submission WHERE submission_id = NEW.submission_id),
            (SELECT target_department_id FROM shared_submission WHERE submission_id = NEW.submission_id)) THEN
            RAISE EXCEPTION 'Approval audience is no longer enforceable' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_role_assignment(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_role_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    membership_org uuid;
    scope_org      uuid;
    role_org       uuid;
BEGIN
    SELECT organization_id
      INTO STRICT membership_org
      FROM organization_membership
     WHERE membership_id = NEW.membership_id;

    SELECT organization_id
      INTO STRICT scope_org
      FROM access_scope
     WHERE access_scope_id = NEW.access_scope_id;

    SELECT organization_id
      INTO role_org
      FROM role
     WHERE role_id = NEW.role_id;

    IF membership_org <> scope_org THEN
        RAISE EXCEPTION 'Membership and access scope must belong to the same organization'
            USING ERRCODE = '23514';
    END IF;

    IF role_org IS NOT NULL AND role_org <> membership_org THEN
        RAISE EXCEPTION 'Organization-specific role cannot be assigned across tenants'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_shared_draft_audience(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_shared_draft_audience() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM role r
        JOIN shared_draft d ON d.shared_draft_id = NEW.shared_draft_id
                           AND d.organization_id = NEW.organization_id
        WHERE r.role_id = NEW.role_id
          AND r.organization_id = NEW.organization_id
          AND NOT r.is_system AND r.status = 'ACTIVE'
          AND EXISTS (SELECT 1 FROM role_permission rp JOIN permission p
              ON p.permission_id = rp.permission_id
              WHERE rp.role_id = r.role_id AND p.code = 'PUBLISHED_CONTENT_VIEW'
                AND p.status = 'ACTIVE')
          AND (r.code <> 'ALL_MEMBERS'
               OR (d.target_scope_type = 'ORGANIZATION'
                   AND d.responsible_department_id IS NOT NULL))
    ) THEN
        RAISE EXCEPTION 'Shared draft audience is not valid for its organization and scope'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_shared_draft_source(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_shared_draft_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE source_org uuid; source_owner uuid;
BEGIN
    IF NEW.source_private_version_id IS NOT NULL THEN
        SELECT om.organization_id, om.membership_id INTO source_org, source_owner
          FROM draft_version v
          JOIN draft_document d ON d.draft_id = v.draft_id
          JOIN private_workspace w ON w.workspace_id = d.workspace_id
          JOIN organization_membership om ON om.membership_id = w.membership_id
         WHERE v.draft_version_id = NEW.source_private_version_id;
        IF source_org IS DISTINCT FROM NEW.organization_id OR source_owner IS DISTINCT FROM NEW.author_membership_id THEN
            RAISE EXCEPTION 'Shared draft private source must belong to its author and organization' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.source_published_version_id IS NOT NULL THEN
        SELECT kb.organization_id INTO source_org
          FROM published_knowledge_version pv
          JOIN knowledge_base kb ON kb.knowledge_base_id = pv.knowledge_base_id
         WHERE pv.published_version_id = NEW.source_published_version_id;
        IF source_org IS DISTINCT FROM NEW.organization_id THEN
            RAISE EXCEPTION 'Shared draft published source must belong to its organization' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_shared_submission(); Type: FUNCTION; Schema: arden; Owner: -
--

CREATE FUNCTION arden.validate_shared_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'arden', 'pg_temp'
    AS $$
DECLARE source_org uuid; submitter_org uuid; department_org uuid; source_row record;
BEGIN
    SELECT organization_id INTO STRICT submitter_org FROM organization_membership
     WHERE membership_id = NEW.submitted_by_membership_id;
    IF NEW.shared_draft_version_id IS NOT NULL THEN
        SELECT d.shared_draft_id, d.organization_id, d.author_membership_id, d.status,
               d.responsible_department_id,
               d.target_scope_type, d.title, d.classification, d.team_tag, d.project_tag,
               d.current_version_no, v.version_no, v.content_uri, v.mime_type, v.content_hash,
               ARRAY(SELECT a.role_id FROM shared_draft_audience a
                     WHERE a.shared_draft_id = d.shared_draft_id ORDER BY a.role_id) AS audience_ids
          INTO STRICT source_row
          FROM shared_draft_version v JOIN shared_draft d ON d.shared_draft_id = v.shared_draft_id
         WHERE v.shared_draft_version_id = NEW.shared_draft_version_id;
        IF source_row.status <> 'ACTIVE'
            OR source_row.shared_draft_id IS DISTINCT FROM NEW.shared_draft_id
            OR source_row.organization_id IS DISTINCT FROM submitter_org
            OR source_row.organization_id IS DISTINCT FROM NEW.organization_id
            OR source_row.author_membership_id IS DISTINCT FROM NEW.submitted_by_membership_id
            OR source_row.current_version_no IS DISTINCT FROM source_row.version_no
            OR source_row.version_no IS DISTINCT FROM NEW.snapshot_version_no
            OR source_row.responsible_department_id IS DISTINCT FROM NEW.responsible_department_id
            OR source_row.target_scope_type IS DISTINCT FROM NEW.target_scope_type
            OR source_row.title IS DISTINCT FROM NEW.title
            OR source_row.classification IS DISTINCT FROM NEW.classification
            OR source_row.team_tag IS DISTINCT FROM NEW.team_tag
            OR source_row.project_tag IS DISTINCT FROM NEW.project_tag
            OR source_row.content_uri IS DISTINCT FROM NEW.content_uri
            OR source_row.mime_type IS DISTINCT FROM NEW.mime_type
            OR source_row.content_hash IS DISTINCT FROM NEW.content_hash
            OR source_row.audience_ids IS DISTINCT FROM NEW.audience_role_ids THEN
            RAISE EXCEPTION 'Submission must freeze the author-owned current shared draft snapshot'
                USING ERRCODE = '23514';
        END IF;
        IF EXISTS (SELECT 1 FROM unnest(NEW.audience_role_ids) AS audience(role_id)
            LEFT JOIN role r ON r.role_id = audience.role_id
            WHERE r.role_id IS NULL OR r.organization_id IS DISTINCT FROM NEW.organization_id
               OR r.status <> 'ACTIVE' OR r.is_system
               OR NOT EXISTS (SELECT 1 FROM role_permission rp JOIN permission p
                   ON p.permission_id = rp.permission_id
                   WHERE rp.role_id = r.role_id AND p.code = 'PUBLISHED_CONTENT_VIEW')) THEN
            RAISE EXCEPTION 'Submission audience is not enforceable' USING ERRCODE = '23514';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM department d
            WHERE d.department_id = NEW.responsible_department_id
              AND d.organization_id = NEW.organization_id AND d.status = 'ACTIVE') THEN
            RAISE EXCEPTION 'Responsible department is not active' USING ERRCODE = '23514';
        END IF;
    ELSE
        SELECT owner_membership.organization_id INTO STRICT source_org
          FROM draft_version v
          JOIN draft_document d ON d.draft_id = v.draft_id
          JOIN private_workspace w ON w.workspace_id = d.workspace_id
          JOIN organization_membership owner_membership ON owner_membership.membership_id = w.membership_id
         WHERE v.draft_version_id = NEW.draft_version_id;
        IF source_org <> submitter_org THEN
            RAISE EXCEPTION 'Submission cannot cross organization boundaries' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.target_department_id IS NOT NULL THEN
        SELECT organization_id INTO STRICT department_org FROM department WHERE department_id = NEW.target_department_id;
        IF department_org <> submitter_org THEN
            RAISE EXCEPTION 'Target department belongs to another organization' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


