SET default_table_access_method = heap;

--
-- Name: access_scope; Type: TABLE; Schema: arden; Owner: -
--

CREATE TABLE arden.access_scope (
    access_scope_id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    department_id uuid,
    scope_type text NOT NULL,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_access_scope_status CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'INACTIVE'::text]))),
    CONSTRAINT ck_access_scope_target CHECK ((((scope_type = 'ORGANIZATION'::text) AND (department_id IS NULL)) OR ((scope_type = 'DEPARTMENT'::text) AND (department_id IS NOT NULL)))),
    CONSTRAINT ck_access_scope_type CHECK ((scope_type = ANY (ARRAY['ORGANIZATION'::text, 'DEPARTMENT'::text])))
);

ALTER TABLE ONLY arden.access_scope FORCE ROW LEVEL SECURITY;


--
-- Name: ai_response; Type: TABLE; Schema: arden; Owner: -
--

CREATE TABLE arden.ai_response (
    response_id uuid DEFAULT gen_random_uuid() NOT NULL,
    question_id uuid NOT NULL,
    response_text text NOT NULL,
    status text DEFAULT 'COMPLETED'::text NOT NULL,
    model_name text NOT NULL,
    model_version text,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_ai_response_status CHECK ((status = ANY (ARRAY['COMPLETED'::text, 'ABSTAINED'::text, 'CLARIFICATION_REQUIRED'::text, 'FAILED'::text])))
);


--
-- Name: audience; Type: TABLE; Schema: arden; Owner: -
--

CREATE TABLE arden.audience (
    audience_id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    kind text NOT NULL,
    department_id uuid,
    name text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    is_managed boolean NOT NULL,
    configuration_version integer DEFAULT 1 NOT NULL,
    created_by_membership_id uuid,
    legacy_role_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_audience_description CHECK ((length(description) <= 300)),
    CONSTRAINT ck_audience_kind CHECK ((kind = ANY (ARRAY['ORGANIZATION_ALL'::text, 'DEPARTMENT_ALL'::text, 'GROUP'::text]))),
    CONSTRAINT ck_audience_name CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 80))),
    CONSTRAINT ck_audience_shape CHECK ((((kind = 'ORGANIZATION_ALL'::text) AND (department_id IS NULL) AND is_managed) OR ((kind = 'DEPARTMENT_ALL'::text) AND (department_id IS NOT NULL) AND is_managed) OR ((kind = 'GROUP'::text) AND (department_id IS NULL) AND (NOT is_managed)))),
    CONSTRAINT ck_audience_status CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'INACTIVE'::text]))),
    CONSTRAINT ck_audience_version CHECK ((configuration_version > 0))
);

ALTER TABLE ONLY arden.audience FORCE ROW LEVEL SECURITY;


