    CONSTRAINT ck_audience_group_membership_status CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'REVOKED'::text, 'EXPIRED'::text]))),
    CONSTRAINT ck_audience_group_membership_validity CHECK (((valid_until IS NULL) OR (valid_until > valid_from)))
