-- Name: shared_submission; Type: TABLE; Schema: arden; Owner: -
--

CREATE TABLE arden.shared_submission (
    submission_id uuid DEFAULT gen_random_uuid() NOT NULL,
    draft_version_id uuid,
    submitted_by_membership_id uuid NOT NULL,
    target_scope_type text NOT NULL,
    target_department_id uuid,
    status text DEFAULT 'PENDING_REVIEW'::text NOT NULL,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid,
    shared_draft_version_id uuid,
    shared_draft_id uuid,
    snapshot_version_no integer,
    responsible_department_id uuid,
    title text,
    classification text,
    team_tag text,
    project_tag text,
    audience_role_ids uuid[],
    policy_version integer,
    content_uri text,
    mime_type text,
    content_hash text,
    submit_request_id uuid,
    publication_state text DEFAULT 'NONE'::text NOT NULL,
    review_rule text DEFAULT 'GRANT_SCOPE'::text NOT NULL,
    CONSTRAINT ck_shared_submission_flow2_snapshot CHECK (((shared_draft_version_id IS NULL) OR ((organization_id IS NOT NULL) AND (shared_draft_id IS NOT NULL) AND (snapshot_version_no IS NOT NULL) AND (snapshot_version_no > 0) AND (responsible_department_id IS NOT NULL) AND (title IS NOT NULL) AND (length(btrim(title)) > 0) AND (classification IS NOT NULL) AND (classification = ANY (ARRAY['INTERNAL'::text, 'CONFIDENTIAL'::text, 'RESTRICTED'::text])) AND (policy_version IS NOT NULL) AND (policy_version = 1) AND (content_uri IS NOT NULL) AND (mime_type IS NOT NULL) AND (mime_type = ANY (ARRAY['text/plain'::text, 'application/pdf'::text])) AND (content_hash IS NOT NULL) AND (content_hash ~ '^[0-9a-f]{64}$'::text) AND (submit_request_id IS NOT NULL) AND (audience_role_ids IS NOT NULL) AND ((cardinality(audience_role_ids) >= 1) AND (cardinality(audience_role_ids) <= 100))))),
    CONSTRAINT ck_shared_submission_one_version CHECK ((num_nonnulls(draft_version_id, shared_draft_version_id) = 1)),
    CONSTRAINT ck_shared_submission_publication_state CHECK ((((status = 'APPROVED'::text) AND (publication_state = ANY (ARRAY['PREPARING'::text, 'ACTIVE'::text, 'FAILED'::text, 'SUPERSEDED'::text]))) OR ((status <> 'APPROVED'::text) AND (publication_state = 'NONE'::text)))),
    CONSTRAINT ck_shared_submission_review_rule CHECK ((review_rule = ANY (ARRAY['LEGACY'::text, 'GRANT_SCOPE'::text]))),
    CONSTRAINT ck_shared_submission_scope CHECK ((target_scope_type = ANY (ARRAY['ORGANIZATION'::text, 'DEPARTMENT'::text]))),
    CONSTRAINT ck_shared_submission_status CHECK ((status = ANY (ARRAY['PENDING_REVIEW'::text, 'APPROVED'::text, 'REJECTED'::text, 'WITHDRAWN'::text]))),
    CONSTRAINT ck_shared_submission_target CHECK ((((target_scope_type = 'ORGANIZATION'::text) AND (target_department_id IS NULL)) OR ((target_scope_type = 'DEPARTMENT'::text) AND (target_department_id IS NOT NULL))))
);

