--
-- Name: access_scope access_scope_admin_access; Type: POLICY; Schema: arden; Owner: -
--

CREATE POLICY access_scope_admin_access ON arden.access_scope TO arden_runtime USING (((organization_id = (NULLIF(current_setting('arden.organization_id'::text, true), ''::text))::uuid) AND (current_setting('arden.org_admin'::text, true) = 'true'::text))) WITH CHECK (((organization_id = (NULLIF(current_setting('arden.organization_id'::text, true), ''::text))::uuid) AND (current_setting('arden.org_admin'::text, true) = 'true'::text)));


--
-- Name: access_scope access_scope_read; Type: POLICY; Schema: arden; Owner: -
--

CREATE POLICY access_scope_read ON arden.access_scope FOR SELECT TO arden_runtime USING (((organization_id = (NULLIF(current_setting('arden.organization_id'::text, true), ''::text))::uuid) OR (EXISTS ( SELECT 1
   FROM arden.organization_membership om
  WHERE ((om.organization_id = access_scope.organization_id) AND (om.user_id = (NULLIF(current_setting('arden.actor_id'::text, true), ''::text))::uuid))))));


