   FROM arden.organization_membership om
  WHERE ((om.membership_id = audience_group_membership.membership_id) AND (om.user_id = (NULLIF(current_setting('arden.actor_id'::text, true), ''::text))::uuid) AND (om.organization_id = audience_group_membership.organization_id) AND (om.status = 'ACTIVE'::text))))));


--
-- Name: audience audience_member_read; Type: POLICY; Schema: arden; Owner: -
--

CREATE POLICY audience_member_read ON arden.audience FOR SELECT TO arden_runtime USING (((organization_id = (NULLIF(current_setting('arden.organization_id'::text, true), ''::text))::uuid) AND (EXISTS ( SELECT 1
   FROM arden.organization_membership om
  WHERE ((om.organization_id = audience.organization_id) AND (om.user_id = (NULLIF(current_setting('arden.actor_id'::text, true), ''::text))::uuid) AND (om.status = 'ACTIVE'::text) AND ((audience.kind = 'ORGANIZATION_ALL'::text) OR ((audience.kind = 'DEPARTMENT_ALL'::text) AND (EXISTS ( SELECT 1
           FROM arden.department_membership dm
          WHERE ((dm.membership_id = om.membership_id) AND (dm.department_id = audience.department_id) AND (dm.status = 'ACTIVE'::text))))) OR ((audience.kind = 'GROUP'::text) AND (EXISTS ( SELECT 1
           FROM arden.audience_group_membership agm
          WHERE ((agm.audience_id = audience.audience_id) AND (agm.membership_id = om.membership_id) AND (agm.status = 'ACTIVE'::text) AND (agm.valid_from <= now()) AND ((agm.valid_until IS NULL) OR (agm.valid_until > now()))))))))))));


