  WHERE ((d.department_id = department_membership.department_id) AND (d.organization_id = (NULLIF(current_setting('arden.organization_id'::text, true), ''::text))::uuid)))) AND (current_setting('arden.org_admin'::text, true) = 'true'::text))) WITH CHECK (((EXISTS ( SELECT 1
