  WHERE (((s.submission_id)::text = current_setting('arden.publishing_submission_id'::text, true)) AND (s.organization_id = knowledge_base.organization_id) AND (s.target_scope_type = knowledge_base.scope_type) AND (NOT (s.target_department_id IS DISTINCT FROM knowledge_base.department_id)) AND (s.status = 'APPROVED'::text) AND arden.actor_has_reviewer_grant(s.organization_id, s.responsible_department_id, s.classification, s.team_tag, s.project_tag))))));


