   FROM ((arden.review_decision rd
     JOIN arden.shared_submission s ON ((s.submission_id = rd.submission_id)))
     JOIN arden.organization_membership om ON ((om.membership_id = rd.reviewer_membership_id)))
  WHERE ((rd.review_decision_id = audit_event.review_decision_id) AND rd.flow2 AND (rd.decision = 'APPROVED'::text) AND (s.status = 'APPROVED'::text) AND (s.organization_id = audit_event.organization_id) AND (om.user_id = (NULLIF(current_setting('arden.actor_id'::text, true), ''::text))::uuid))))));


