  WHERE ((s.submission_id = review_decision.submission_id) AND (s.status = 'PENDING_REVIEW'::text) AND ((current_setting('arden.org_admin'::text, true) = 'true'::text) OR ((s.submitted_by_membership_id <> review_decision.reviewer_membership_id) AND arden.actor_has_reviewer_grant(s.organization_id, s.responsible_department_id, s.classification, s.team_tag, s.project_tag)))))) AND (EXISTS ( SELECT 1
