   FROM arden.organization_membership om
  WHERE ((om.membership_id = role_assignment.membership_id) AND (om.organization_id = (NULLIF(current_setting('arden.organization_id'::text, true), ''::text))::uuid)))) AND (EXISTS ( SELECT 1
   FROM arden.access_scope s
  WHERE ((s.access_scope_id = role_assignment.access_scope_id) AND (s.organization_id = (NULLIF(current_setting('arden.organization_id'::text, true), ''::text))::uuid)))) AND (EXISTS ( SELECT 1
